const h = params.height;
const baseW = h * 0.48;
const baseH = h * 0.075;
const coneBottom = baseH;
const coneTop = h;
const coneH = coneTop - coneBottom;
const orange = params.color;
const white = '#f3f1df';
const rubber = { preset: 'rubber', color: '#17191a', roughness: 0.92 };
const coneMat = { preset: 'plastic', roughness: 0.42, flatShading: true };
api.add(api.box(baseW, baseH * 0.52, baseW).translate(0, baseH * 0.26, 0), rubber);
api.add(api.box(baseW * 0.91, baseH * 0.48, baseW * 0.91).translate(0, baseH * 0.76, 0), rubber);
const cornerPad = h * 0.018;
const padOffset = baseW * 0.5 - cornerPad * 0.8;
for (let ix = -1; ix <= 1; ix += 2) {
  for (let iz = -1; iz <= 1; iz += 2) {
    api.add(api.box(cornerPad * 1.6, baseH * 0.18, cornerPad * 1.6).translate(ix * padOffset, baseH * 0.09, iz * padOffset), rubber);
  }
}
const footR = h * 0.205;
const footH = h * 0.045;
api.add(api.cylinder(footR * 0.92, footR, footH, 24).translate(0, baseH + footH * 0.5, 0), { preset: 'plastic', color: orange, roughness: 0.48, flatShading: true });
const y0 = coneBottom + footH * 0.55;
const y1 = coneBottom + coneH * 0.39;
const y2 = coneBottom + coneH * 0.50;
const y3 = coneBottom + coneH * 0.61;
const y4 = coneBottom + coneH * 0.70;
const r0 = h * 0.175;
const rAt = (y) => r0 + (h * 0.045 - r0) * ((y - y0) / (coneTop - y0));
const profile = [
  [0, y0], [r0, y0],
  [rAt(y1), y1], [rAt(y1), y1],
  [rAt(y2), y2], [rAt(y2), y2],
  [rAt(y3), y3], [rAt(y3), y3],
  [rAt(y4), y4], [rAt(y4), y4],
  [h * 0.045, coneTop], [0, coneTop]
];
const cone = api.lathe(profile, 28);
cone.vertexColor((x, y, z) => ((y >= y1 && y <= y2) || (y >= y3 && y <= y4)) ? white : orange);
api.add(cone, coneMat);
api.add(api.torus(rAt(y1) * 0.995, h * 0.006).rotate(90, 0, 0).translate(0, y1, 0), { preset: 'plastic', color: white, roughness: 0.3 });
api.add(api.torus(rAt(y3) * 0.995, h * 0.006).rotate(90, 0, 0).translate(0, y3, 0), { preset: 'plastic', color: white, roughness: 0.3 });
api.collider({ kind: 'box', halfExtents: [baseW * 0.5, baseH * 0.5, baseW * 0.5], offset: [0, baseH * 0.5, 0] });
api.collider({ kind: 'cylinder', radius: r0, halfHeight: (coneTop - y0) * 0.5, offset: [0, y0 + (coneTop - y0) * 0.5, 0] });
return api.build();
